import sys
from heapq import heappush, heappop

def main():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    n = int(input_data[0])
    ops = []
    for i in range(1, n + 1):
        parts = input_data[i].split()
        ops.append(parts)

    result_ops = []
    heap = []

    for op in ops:
        if op[0] == 'insert':
            val = int(op[1])
            heappush(heap, val)
            result_ops.append(f"insert {val}")
        elif op[0] == 'getMin':
            val = int(op[1])
            while heap and heap[0] < val:
                heappop(heap)
                result_ops.append("removeMin")
            if not heap or heap[0] > val:
                heappush(heap, val)
                result_ops.append(f"insert {val}")
            result_ops.append(f"getMin {val}")
        elif op[0] == 'removeMin':
            if not heap:
                heappush(heap, 0)
                result_ops.append("insert 0")
            heappop(heap)
            result_ops.append("removeMin")

    while heap:
        heappop(heap)
        result_ops.append("removeMin")

    print(len(result_ops))
    for r in result_ops:
        print(r)

if __name__ == "__main__":
    main()
